-- Migration 025: expanded checkpoint explanations and try-it solutions for SMA lessons.
-- Auto-generated by json_encode_lesson_explanations_v2.dart.
-- Surgically patches skills.lesson JSONB without re-emitting the full lesson.
BEGIN;

CREATE OR REPLACE FUNCTION public._patch_cp_sma(
    p_skill_code TEXT,
    p_stem_fr TEXT,
    p_new_explanation TEXT
) RETURNS BOOLEAN AS $$
DECLARE
    v_lesson JSONB;
    v_section_idx INT;
    v_block_idx INT;
    v_question_idx INT;
    v_block JSONB;
    v_questions JSONB;
    v_question JSONB;
    v_found BOOLEAN := FALSE;
    v_n_sections INT;
    v_n_blocks INT;
    v_n_questions INT;
BEGIN
    SELECT lesson INTO v_lesson FROM public.skills WHERE code = p_skill_code;
    IF v_lesson IS NULL OR v_lesson->'sections' IS NULL THEN RETURN FALSE; END IF;
    v_n_sections := jsonb_array_length(v_lesson->'sections');
    FOR v_section_idx IN 0..(v_n_sections - 1) LOOP
        IF v_lesson->'sections'->v_section_idx->'blocks' IS NULL THEN CONTINUE; END IF;
        v_n_blocks := jsonb_array_length(v_lesson->'sections'->v_section_idx->'blocks');
        FOR v_block_idx IN 0..(v_n_blocks - 1) LOOP
            v_block := v_lesson->'sections'->v_section_idx->'blocks'->v_block_idx;
            IF v_block->>'kind' <> 'checkpoint' THEN CONTINUE; END IF;
            v_questions := v_block->'questions';
            IF v_questions IS NULL THEN CONTINUE; END IF;
            v_n_questions := jsonb_array_length(v_questions);
            FOR v_question_idx IN 0..(v_n_questions - 1) LOOP
                v_question := v_questions->v_question_idx;
                IF v_question->>'stem_fr' = p_stem_fr THEN
                    v_lesson := jsonb_set(
                        v_lesson,
                        ARRAY['sections', v_section_idx::text, 'blocks', v_block_idx::text, 'questions', v_question_idx::text, 'explanation_fr'],
                        to_jsonb(p_new_explanation)
                    );
                    v_found := TRUE;
                END IF;
            END LOOP;
        END LOOP;
    END LOOP;
    IF v_found THEN
        UPDATE public.skills SET lesson = v_lesson WHERE code = p_skill_code;
    END IF;
    RETURN v_found;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public._patch_tryit_sma(
    p_skill_code TEXT,
    p_problem_fr TEXT,
    p_new_hint TEXT,
    p_new_solution TEXT
) RETURNS BOOLEAN AS $$
DECLARE
    v_lesson JSONB;
    v_section_idx INT;
    v_block_idx INT;
    v_block JSONB;
    v_found BOOLEAN := FALSE;
    v_n_sections INT;
    v_n_blocks INT;
BEGIN
    SELECT lesson INTO v_lesson FROM public.skills WHERE code = p_skill_code;
    IF v_lesson IS NULL OR v_lesson->'sections' IS NULL THEN RETURN FALSE; END IF;
    v_n_sections := jsonb_array_length(v_lesson->'sections');
    FOR v_section_idx IN 0..(v_n_sections - 1) LOOP
        IF v_lesson->'sections'->v_section_idx->'blocks' IS NULL THEN CONTINUE; END IF;
        v_n_blocks := jsonb_array_length(v_lesson->'sections'->v_section_idx->'blocks');
        FOR v_block_idx IN 0..(v_n_blocks - 1) LOOP
            v_block := v_lesson->'sections'->v_section_idx->'blocks'->v_block_idx;
            IF v_block->>'kind' <> 'try_it' THEN CONTINUE; END IF;
            IF v_block->>'problem_fr' = p_problem_fr THEN
                v_lesson := jsonb_set(
                    v_lesson,
                    ARRAY['sections', v_section_idx::text, 'blocks', v_block_idx::text, 'hint_fr'],
                    to_jsonb(p_new_hint)
                );
                v_lesson := jsonb_set(
                    v_lesson,
                    ARRAY['sections', v_section_idx::text, 'blocks', v_block_idx::text, 'solution_fr'],
                    to_jsonb(p_new_solution)
                );
                v_found := TRUE;
            END IF;
        END LOOP;
    END LOOP;
    IF v_found THEN
        UPDATE public.skills SET lesson = v_lesson WHERE code = p_skill_code;
    END IF;
    RETURN v_found;
END;
$$ LANGUAGE plpgsql;

SELECT public._patch_tryit_sma('arithmetic_seq', 'Calcule $2 + 5 + 8 + \dots + 50$ (raison 3, partant de 2).', 'On a une suite arithmétique de premier terme 2 et raison 3. La somme $u_p + u_{p+1} + \dots + u_n$ vaut (nombre de termes) × (premier + dernier) / 2. Première étape : trouver combien de termes la somme contient. Le terme général est $u_n = 2 + 3n$ (avec $u_0 = 2$). Trouve le rang $n$ tel que $u_n = 50$, ajoute 1 pour le nombre de termes, puis applique la formule.', 'On reconnaît la somme d''une suite arithmétique de premier terme $u_0 = 2$ et de raison $r = 3$. Le terme général est $u_n = u_0 + n r = 2 + 3n$. On cherche $n$ tel que $u_n = 50$ : $2 + 3n = 50$, donc $3n = 48$, donc $n = 16$. **Attention** : le rang 16 correspond au 17ème terme (les rangs commencent à 0). On a donc 17 termes en tout. La formule de Gauss donne $S = (\text{nb termes}) \times \dfrac{\text{premier} + \text{dernier}}{2} = 17 \times \dfrac{2 + 50}{2} = 17 \times 26 = 442$. **Vérification rapide** : la moyenne (2+50)/2 = 26, multipliée par le nombre de termes 17 = 442. Cohérent.');
SELECT public._patch_tryit_sma('limit_calc', 'Calcule $\lim_{x\to 1} \dfrac{x^2 - 1}{x - 1}$.', 'On commence toujours par tenter la substitution directe. Ici, $x = 1$ donne numérateur $1 - 1 = 0$ et dénominateur $1 - 1 = 0$ : forme indéterminée $0/0$. **Cette forme est presque toujours le signe d''une factorisation cachée** — numérateur et dénominateur ont une racine commune $x = 1$. Pense à l''identité remarquable $a^2 - b^2 = (a-b)(a+b)$.', 'Substitution directe en $x = 1$ : numérateur $1^2 - 1 = 0$, dénominateur $1 - 1 = 0$. **Forme indéterminée $\frac{0}{0}$** — c''est le signal qu''il faut factoriser. On utilise l''identité remarquable $a^2 - b^2 = (a-b)(a+b)$ avec $a = x$ et $b = 1$ : $x^2 - 1 = (x-1)(x+1)$. La fraction se réécrit $\dfrac{(x-1)(x+1)}{x-1}$. Le facteur $(x-1)$ se simplifie au numérateur et au dénominateur — c''est légitime parce qu''on étudie la limite *quand* $x \to 1$, donc avec $x \ne 1$, donc $x - 1 \ne 0$. Il reste $\lim_{x \to 1}(x+1) = 1 + 1 = 2$. Le résultat 2 est aussi la valeur de la dérivée de $x^2$ en $x = 1$ — ce taux d''accroissement est l''archétype de la définition de la dérivée.');
SELECT public._patch_tryit_sma('tvi', 'Montre que $\cos(x) = x$ admet une solution dans $[0, \pi/2]$.', 'L''astuce classique : ramène l''équation à la forme $g(x) = 0$ en posant $g(x) = \cos(x) - x$. Une solution de $\cos(x) = x$ est alors un zéro de $g$. Pour appliquer le TVI, vérifie que $g$ est continue sur $[0, \pi/2]$ (oui : différence de fonctions continues), puis évalue $g$ aux bornes pour montrer un changement de signe.', 'On pose $g(x) = \cos(x) - x$, ainsi $\cos(x) = x \iff g(x) = 0$. Étape 1 : $g$ est **continue** sur $[0, \pi/2]$ comme différence de deux fonctions continues ($\cos$ et l''identité). Étape 2 : on évalue aux bornes. $g(0) = \cos(0) - 0 = 1 - 0 = 1 > 0$. $g(\pi/2) = \cos(\pi/2) - \pi/2 = 0 - \pi/2 \approx -1{,}57 < 0$. Étape 3 : 0 est compris entre $g(\pi/2) < 0$ et $g(0) > 0$. **Par le théorème des valeurs intermédiaires**, il existe au moins un $c \in ]0, \pi/2[$ tel que $g(c) = 0$, c''est-à-dire $\cos(c) = c$. Le TVI prouve l''existence sans donner la valeur ; numériquement, $c \approx 0{,}739$. **Astuce mémo** : pour toute équation $f(x) = a$, transforme en $f(x) - a = 0$, puis cherche un changement de signe.');
SELECT public._patch_tryit_sma('deriv_apps', 'Étudie les variations de $f(x) = x^3 - 3x$ sur $\mathbb{R}$.', 'Le plan standard pour étudier les variations d''une fonction : (1) calculer $f''(x)$, (2) résoudre $f''(x) = 0$ pour trouver les points critiques, (3) faire un tableau de signes de $f''$, (4) déduire les variations de $f$. Ici $f$ est un polynôme de degré 3, donc $f''$ sera un polynôme de degré 2 — facile à factoriser.', '**Étape 1 — Calcul de $f''$** : $f(x) = x^3 - 3x$, donc $f''(x) = 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$. **Étape 2 — Points critiques** : $f''(x) = 0 \iff x = -1$ ou $x = 1$. Ce sont les candidats extrema. **Étape 3 — Tableau de signes** : le coefficient dominant de $f''$ est positif, donc $f''$ est positive en dehors des racines et négative entre elles. Sur $]-\infty, -1[$ : $f'' > 0$ → $f$ croît. Sur $]-1, 1[$ : $f'' < 0$ → $f$ décroît. Sur $]1, +\infty[$ : $f'' > 0$ → $f$ croît. **Étape 4 — Conclusion** : $f$ admet un **maximum local** en $x = -1$ avec $f(-1) = -1 + 3 = 2$, et un **minimum local** en $x = 1$ avec $f(1) = 1 - 3 = -2$. La courbe a la forme caractéristique en S des polynômes de degré 3 à coefficient dominant positif.');
SELECT public._patch_tryit_sma('definite_integral', 'Calcule $\int_0^1 (3x^2 + 2x)\,dx$.', 'Une intégrale définie d''un polynôme se calcule en deux temps : trouver une primitive $F$, puis appliquer la formule de Newton-Leibniz $F(b) - F(a)$. Pour $x^n$, la primitive est $x^{n+1}/(n+1)$. Linéarité de l''intégrale : $\int (f + g) = \int f + \int g$, et $\int k f = k \int f$.', '**Étape 1 — Primitive** : on cherche $F$ telle que $F''(x) = 3x^2 + 2x$. Par linéarité, on intègre terme à terme. Pour $3x^2$ : primitive $3 \cdot x^3/3 = x^3$. Pour $2x$ : primitive $2 \cdot x^2/2 = x^2$. Donc $F(x) = x^3 + x^2$. **On peut vérifier en dérivant** : $F''(x) = 3x^2 + 2x$ ✓. **Étape 2 — Newton-Leibniz** : $\int_0^1 (3x^2 + 2x)\,dx = F(1) - F(0) = (1^3 + 1^2) - (0^3 + 0^2) = 2 - 0 = 2$. **Vérification dimensionnelle** : c''est une aire sous une courbe positive sur $[0, 1]$, donc le résultat doit être positif et de l''ordre de grandeur de la hauteur moyenne (≈ 2,5) fois la largeur (1). On obtient 2 — cohérent.');

SELECT public._patch_cp_sma('arithmetic_seq', 'Si $u_n = 2n+1$, que vaut $u_3$ ?', 'Pour calculer $u_3$, on remplace simplement $n$ par 3 dans la formule explicite : $u_3 = 2 \times 3 + 1 = 6 + 1 = 7$. **Attention au piège** : la formule donne directement le terme — pas besoin de calculer $u_0, u_1, u_2$ d''abord. Pour une formule explicite $u_n = an + b$, c''est un calcul direct.');
SELECT public._patch_cp_sma('arithmetic_seq', 'Quelle est la raison de la suite $5, 9, 13, 17$ ?', 'Une suite est arithmétique si la **différence entre deux termes consécutifs** est constante. On vérifie : $9 - 5 = 4$, $13 - 9 = 4$, $17 - 13 = 4$. La différence est bien constante et vaut 4 — c''est la raison. **Le piège classique** : confondre la valeur du premier terme (5) avec la raison (4). La raison décrit la *progression*, pas la *position*.');
SELECT public._patch_cp_sma('arithmetic_seq', 'Si $u_0 = 2$ et $r = 3$, que vaut $u_{10}$ ?', 'Pour une suite arithmétique de premier terme $u_0$ et raison $r$, le terme général est $u_n = u_0 + n r$ — chaque terme s''obtient en partant de $u_0$ et en ajoutant $r$ exactement $n$ fois. Application : $u_{10} = 2 + 10 \times 3 = 2 + 30 = 32$. **Attention** : c''est $n r$, pas $(n-1) r$ — la formule part de $u_0$, pas de $u_1$.');
SELECT public._patch_cp_sma('arithmetic_seq', 'Somme de $1 + 2 + \dots + 10$ ?', 'C''est la somme des entiers de 1 à 10, qu''on calcule par la **formule de Gauss** : $1 + 2 + \dots + n = \dfrac{n(n+1)}{2}$. Application avec $n = 10$ : $S = \dfrac{10 \times 11}{2} = 55$. La formule générale pour une somme arithmétique : (nombre de termes) × (premier + dernier) / 2 — ici $10 \times (1+10)/2 = 55$. Les deux formes donnent le même résultat.');
SELECT public._patch_cp_sma('geometric_seq', 'Dans $2, 6, 18, 54$, on multiplie chaque terme par :', 'Une suite est géométrique si le **rapport entre deux termes consécutifs** est constant — ce rapport est la raison $q$. On calcule : $6/2 = 3$, $18/6 = 3$, $54/18 = 3$. La raison est $q = 3$. **Piège** : ne pas confondre raison géométrique (multiplication) et raison arithmétique (addition). Ici 6 - 2 = 4, mais cette différence n''est pas constante (18 - 6 = 12), donc la suite n''est pas arithmétique.');
SELECT public._patch_cp_sma('geometric_seq', 'Quelle est la raison de $8, 4, 2, 1, 0{,}5$ ?', 'On calcule le rapport entre termes consécutifs : $4/8 = 1/2$, $2/4 = 1/2$, $1/2 = 1/2$, $0{,}5/1 = 1/2$. Le rapport est constant et vaut $1/2$ : la suite est géométrique de raison $q = 1/2$. **Équivalent** : on divise par 2, ce qui revient à multiplier par $1/2$. Avec $|q| < 1$, la suite est strictement décroissante vers 0.');
SELECT public._patch_cp_sma('geometric_seq', '$u_0 = 1$, $q = 3$. Que vaut $u_4$ ?', 'Pour une suite géométrique : $u_n = u_0 \cdot q^n$. On part de $u_0 = 1$ et on multiplie par $q = 3$ exactement $n = 4$ fois. Application : $u_4 = 1 \cdot 3^4 = 81$. **Piège classique** : confondre $q^n$ et $n q$. Pour les suites géométriques c''est toujours une **puissance** $q^n$, pas un produit. On peut vérifier en énumérant : $u_0 = 1, u_1 = 3, u_2 = 9, u_3 = 27, u_4 = 81$.');
SELECT public._patch_cp_sma('geometric_seq', 'Que vaut $1 + 1/2 + 1/4 + \dots$ (somme infinie, $|q|<1$) ?', 'Pour une suite géométrique de raison $|q| < 1$, la **somme infinie** converge vers $\dfrac{u_0}{1 - q}$. Ici $u_0 = 1$ et $q = 1/2$, donc $S = \dfrac{1}{1 - 1/2} = \dfrac{1}{1/2} = 2$. **Intuition** : chaque terme ajoute la moitié de ce qui restait à atteindre 2 — paradoxe de Zénon. C''est cohérent avec une vérification : $1 + 0{,}5 + 0{,}25 + 0{,}125 + \dots$ s''approche de 2 sans jamais le dépasser.');
SELECT public._patch_cp_sma('seq_convergence', '$\lim 1/n^2$ vaut :', 'Quand $n \to +\infty$, $n^2 \to +\infty$ encore plus vite. Une fraction de la forme « constante / quelque chose qui tend vers $+\infty$ » tend toujours vers 0. Donc $\lim_{n \to \infty} 1/n^2 = 0$. **Plus généralement** : pour tout $\alpha > 0$, $\lim 1/n^\alpha = 0$. Cette convergence est le pilier des théorèmes de comparaison.');
SELECT public._patch_cp_sma('seq_convergence', '$\lim (0{,}5)^n$ vaut :', 'C''est une suite géométrique de raison $q = 0{,}5$. Comme $|q| < 1$, on a $q^n \to 0$ quand $n \to +\infty$ — chaque terme vaut la moitié du précédent, donc tend exponentiellement vers 0. **Règle générale** : $q^n \to 0$ ssi $|q| < 1$, $q^n \to +\infty$ si $q > 1$, $q^n = 1$ si $q = 1$, et $q^n$ oscille (n''a pas de limite) si $q \le -1$.');
SELECT public._patch_cp_sma('seq_convergence', '$\lim 2^n$ vaut :', 'C''est une suite géométrique de raison $q = 2 > 1$. Quand on multiplie par 2 à chaque étape, la suite **diverge vers $+\infty$** — la croissance est exponentielle. $\lim 2^n = +\infty$. Pour comparaison : $2^{10} = 1024$, $2^{20} \approx 10^6$, $2^{30} \approx 10^9$. Cette croissance bat n''importe quel polynôme à long terme.');
SELECT public._patch_cp_sma('seq_convergence', 'Le théorème des gendarmes sert à :', 'Le **théorème des gendarmes** (ou d''encadrement) sert à démontrer une convergence par encadrement : si pour tout $n$, $a_n \le u_n \le b_n$ avec $\lim a_n = \lim b_n = \ell$, alors $\lim u_n = \ell$. **Application typique** : encadrer $u_n = \sin(n)/n$ par $-1/n \le u_n \le 1/n$, qui tendent tous deux vers 0, donc $u_n \to 0$. Le théorème ne *calcule* pas la limite : il *prouve* qu''elle existe et la donne via les gardiens.');
SELECT public._patch_cp_sma('seq_recursive', 'Si $f$ est continue et $u_n \to \ell$, alors :', 'Si $u_{n+1} = f(u_n)$ avec $f$ continue et $u_n \to \ell$, on peut **passer à la limite des deux côtés** : $u_{n+1} \to \ell$ aussi (car c''est la même suite décalée), et $f(u_n) \to f(\ell)$ par continuité de $f$. On obtient l''équation $\ell = f(\ell)$. **Méthode standard** : pour trouver les limites possibles d''une suite récurrente, on résout l''équation des points fixes $\ell = f(\ell)$. Mais attention : cela suppose que la limite existe — il faut le démontrer séparément (par monotonie + bornes par exemple).');
SELECT public._patch_cp_sma('seq_recursive', 'Pour conclure à la convergence d''une suite récurrente, on cherche typiquement à montrer qu''elle est :', 'Le théorème de la **limite monotone** : toute suite **monotone et bornée** converge. Concrètement, si on montre que $(u_n)$ est croissante et majorée (ou décroissante et minorée), elle converge vers une limite finie. Combiné à l''équation des points fixes $\ell = f(\ell)$, cela donne la valeur. **Sans monotonie ni bornes, on ne peut rien conclure** — la suite peut osciller, diverger, etc. C''est l''outil principal pour les suites récurrentes en Bac.');
SELECT public._patch_cp_sma('seq_adjacent', 'Si $(u_n)$ croissante, $(v_n)$ décroissante et $v_n - u_n \to 0$, alors :', 'C''est exactement le **théorème des suites adjacentes** : deux suites $(u_n)$ croissante et $(v_n)$ décroissante telles que $v_n - u_n \to 0$ convergent toutes les deux vers la **même limite**. Géométriquement, l''intervalle $[u_n, v_n]$ se rétrécit autour d''un point unique. Application classique : encadrement de $\pi$ par les périmètres de polygones inscrit/circonscrit. **Attention** : il faut bien la condition $v_n - u_n \to 0$ — sans elle, les suites peuvent converger vers des limites différentes.');
SELECT public._patch_cp_sma('limit_def', '$\lim_{x\to 0} x^2 = ?$', 'La fonction $x \mapsto x^2$ est polynômiale, donc continue en tout point de $\mathbb{R}$. Quand une fonction est continue en un point $a$, sa limite y vaut simplement $f(a)$ — la substitution directe est valide. Application : $\lim_{x \to 0} x^2 = 0^2 = 0$. **Toujours essayer la substitution directe avant de chercher des techniques avancées** — souvent ça marche.');
SELECT public._patch_cp_sma('limit_def', '$\lim_{x\to +\infty} \frac{1}{x} = ?$', 'Quand $x$ tend vers $+\infty$, le numérateur 1 reste fixe alors que le dénominateur $x$ devient arbitrairement grand. Une fraction de la forme « constante / quelque chose qui tend vers l''infini » tend toujours vers 0. Cette limite est l''archétype de la décroissance vers zéro à l''infini, et fonde toute la théorie des asymptotes horizontales.');
SELECT public._patch_cp_sma('limit_calc', '$\lim_{x\to 4} \frac{x^2-16}{x-4} = ?$', 'Substitution directe en $x = 4$ : numérateur $16 - 16 = 0$, dénominateur $4 - 4 = 0$, **forme indéterminée $0/0$**. On factorise via l''identité remarquable $a^2 - b^2 = (a-b)(a+b)$ : $x^2 - 16 = (x-4)(x+4)$. La fraction se réécrit $\dfrac{(x-4)(x+4)}{x-4}$. Le facteur $(x-4)$ se simplifie (légitime puisque $x \ne 4$ dans la limite), il reste $\lim_{x \to 4}(x+4) = 8$. **Pattern à retenir** : forme $0/0 \Rightarrow$ chercher une factorisation cachée.');
SELECT public._patch_cp_sma('limit_calc', '$\lim_{x\to +\infty} \frac{3x+1}{x+5} = ?$', 'Quand $x \to +\infty$, numérateur et dénominateur tendent vers $+\infty$ — forme indéterminée $\infty/\infty$. **Astuce standard** : factoriser $x$ au plus haut degré au numérateur et au dénominateur. $\dfrac{3x+1}{x+5} = \dfrac{x(3 + 1/x)}{x(1 + 5/x)} = \dfrac{3 + 1/x}{1 + 5/x}$. Quand $x \to +\infty$, $1/x \to 0$ et $5/x \to 0$, donc la fraction tend vers $3/1 = 3$. **Règle rapide** : pour un quotient de polynômes de même degré à l''infini, la limite est le rapport des coefficients dominants.');
SELECT public._patch_cp_sma('limit_calc', '$\lim_{x\to 0^+} \frac{1}{x} = ?$', 'Quand $x \to 0$ par valeurs positives ($x > 0$ très petit), le dénominateur $x$ tend vers 0 par valeurs positives, et $1/x$ devient arbitrairement grand et positif. Donc $\lim_{x \to 0^+} 1/x = +\infty$. **Attention au signe de la limite latérale** : $\lim_{x \to 0^-} 1/x = -\infty$ (car $x$ tend vers 0 par valeurs négatives). Pour $1/x$ en 0, la limite globale **n''existe pas** — les limites à gauche et à droite diffèrent.');
SELECT public._patch_cp_sma('continuity', 'Une fonction $f$ est continue en $a$ ssi :', 'Définition formelle : $f$ est **continue en $a$** ssi $\lim_{x \to a} f(x) = f(a)$. Cela exige trois choses simultanément : (1) $f$ est définie en $a$, (2) la limite $\lim_{x \to a} f(x)$ existe, (3) cette limite égale $f(a)$. Géométriquement : on peut tracer la courbe en passant par $a$ sans lever le crayon. **Les trois conditions sont nécessaires** — il existe des fonctions définies en $a$ avec une limite, mais où la limite ne vaut pas $f(a)$ : elles sont alors discontinues en $a$.');
SELECT public._patch_cp_sma('tvi', 'Le TVI permet de :', 'Le **théorème des valeurs intermédiaires** garantit l''**existence** d''une solution sans donner sa valeur. Si $f$ est continue sur $[a, b]$ et $k$ est une valeur entre $f(a)$ et $f(b)$, alors il existe au moins un $c \in [a, b]$ tel que $f(c) = k$. Pour calculer $c$ exactement, il faut résoudre l''équation. **C''est un théorème d''existence pure** — son corollaire le plus utilisé : si $f(a) f(b) < 0$, alors $f$ s''annule au moins une fois entre $a$ et $b$.');
SELECT public._patch_cp_sma('tvi', '$f$ continue sur $[0,1]$, $f(0) = 3$, $f(1) = -2$. Le TVI garantit qu''il existe $c$ tel que :', 'On vérifie d''abord la continuité (donnée). Le TVI s''applique aux valeurs comprises **entre** $f(0) = 3$ et $f(1) = -2$, c''est-à-dire dans l''intervalle $[-2, 3]$. Parmi les options : 5 et $-3$ et $4$ sont en dehors, mais **0 est dedans** ($-2 < 0 < 3$). Donc le TVI garantit l''existence d''un $c \in ]0, 1[$ tel que $f(c) = 0$. **Idée à retenir** : le TVI ne dit rien des valeurs hors de l''intervalle des bornes.');
SELECT public._patch_cp_sma('deriv_basic', '$f''(a)$ représente géométriquement :', 'Géométriquement, $f''(a)$ est la **pente de la tangente** à la courbe $y = f(x)$ au point d''abscisse $a$. Mathématiquement, c''est la limite du taux d''accroissement $\dfrac{f(a+h) - f(a)}{h}$ quand $h \to 0$ — c''est-à-dire la pente d''une corde infiniment courte, qui devient la tangente à la limite. **Interprétation physique** : si $f(t)$ est une position, $f''(t)$ est la vitesse instantanée.');
SELECT public._patch_cp_sma('deriv_basic', '$f(x) = x^2$. Que vaut $f''(3)$ ?', 'Pour $f(x) = x^2$, on applique la règle des puissances $(x^n)'' = n x^{n-1}$ avec $n = 2$ : $f''(x) = 2x$. En $x = 3$ : $f''(3) = 2 \cdot 3 = 6$. Cela signifie qu''au point $(3, 9)$ de la parabole, la tangente a une pente de 6 — son équation est $y = 6(x - 3) + 9 = 6x - 9$. **À mémoriser** : $(x^n)'' = n x^{n-1}$ est l''une des règles les plus utilisées.');
SELECT public._patch_cp_sma('deriv_basic', '$f(x) = 5x + 1$. Que vaut $f''(2)$ ?', 'Une fonction affine $f(x) = ax + b$ a une dérivée constante $f''(x) = a$ partout. Géométriquement, c''est cohérent : la courbe est elle-même une droite, donc la tangente coïncide avec la courbe et a la même pente partout — $a$, le coefficient directeur. Pour $f(x) = 5x + 1$, $f''(x) = 5$ pour tout $x$, donc $f''(2) = 5$. **Pas de calcul à faire** : la dérivée d''une affine ne dépend pas du point.');
SELECT public._patch_cp_sma('deriv_rules', '$(uv)'' = ?$', 'La **règle du produit** dit que la dérivée d''un produit de fonctions $u(x) v(x)$ est $u'' v + u v''$ — pas $u'' v''$ (erreur classique). Démonstration intuitive : la variation du rectangle $u \times v$ vient de la variation de $u$ multipliée par $v$, plus la variation de $v$ multipliée par $u$. Application typique : $(x \cdot e^x)'' = 1 \cdot e^x + x \cdot e^x = (1 + x) e^x$.');
SELECT public._patch_cp_sma('deriv_rules', '$(u/v)'' = ?$', 'La **règle du quotient** : $\left(\dfrac{u}{v}\right)'' = \dfrac{u'' v - u v''}{v^2}$. **L''ordre dans le numérateur compte** : c''est $u'' v - u v''$, pas $u v'' - u'' v$ — inverser donne le mauvais signe. Le dénominateur est toujours $v^2$ (carré). Application typique : $\left(\dfrac{1}{x}\right)'' = \dfrac{0 \cdot x - 1 \cdot 1}{x^2} = -\dfrac{1}{x^2}$ — cohérent avec la règle des puissances $(x^{-1})'' = -x^{-2}$.');
SELECT public._patch_cp_sma('deriv_rules', '$(\sin x)'' = ?$', '$(\sin x)'' = \cos x$. Cette dérivée est l''une des fondamentales du programme. **Astuce mnémotechnique** : sin → cos (sans signe), cos → -sin (avec signe). Géométriquement : la pente de $\sin$ en 0 vaut 1 (= $\cos 0$), elle s''annule en $\pi/2$ (= $\cos(\pi/2) = 0$), devient $-1$ en $\pi$ (= $\cos \pi = -1$). Tout cohérent.');
SELECT public._patch_cp_sma('deriv_rules', '$(e^x)'' = ?$', '$(e^x)'' = e^x$ — la fonction exponentielle est sa propre dérivée. **C''est sa propriété caractéristique** : elle est l''unique solution de $f'' = f$ avec $f(0) = 1$. Cela explique son omniprésence en physique (lois de désintégration, charge de condensateur, croissance de population) — partout où la vitesse est proportionnelle à la quantité présente, on tombe sur l''exponentielle.');
SELECT public._patch_cp_sma('deriv_apps', 'Si $f''(x) > 0$ sur un intervalle, $f$ est :', '**Théorème de variation** : si $f$ est dérivable sur un intervalle $I$ et $f'' > 0$ sur $I$, alors $f$ est **strictement croissante** sur $I$. Intuition : pente positive partout = la courbe monte. Réciproquement, $f'' < 0$ ⇒ $f$ décroissante ; $f'' = 0$ ⇒ $f$ constante. C''est l''outil clé pour étudier les variations : on calcule $f''$, on étudie son signe, on en déduit les variations de $f$.');
SELECT public._patch_cp_sma('deriv_apps', 'Un extremum local de $f$ se trouve typiquement où :', '**Théorème de Fermat** : un extremum local d''une fonction dérivable est un point où $f''(x) = 0$ — appelé point critique. Géométriquement, la tangente y est horizontale. **Attention** : la réciproque est fausse : $f''(x) = 0$ n''implique pas un extremum (exemple : $f(x) = x^3$ en 0, où $f''(0) = 0$ mais c''est un point d''inflexion, pas un extremum). Pour confirmer un extremum, étudier le signe de $f''$ autour du point.');
SELECT public._patch_cp_sma('primitives', 'Une primitive de $x^2$ est :', 'Pour primitiver $x^n$, on applique la règle inverse de la dérivée : $\int x^n\,dx = \dfrac{x^{n+1}}{n+1} + C$. Avec $n = 2$ : primitive de $x^2$ = $\dfrac{x^3}{3} + C$. **Vérification** : dériver $x^3/3$ donne bien $3x^2/3 = x^2$ ✓. La constante $C$ est libre — toute primitive est définie à une constante près. Si la question demande *une* primitive (pas *la* primitive), la plus simple est avec $C = 0$ : $x^3/3$.');
SELECT public._patch_cp_sma('primitives', 'Une primitive de $\cos x$ est :', 'Une primitive de $\cos x$ est $\sin x$ (à une constante près). **Vérification** : $(\sin x)'' = \cos x$ ✓. Attention au piège du signe : la dérivée de $\cos x$ est $-\sin x$ (avec signe), mais la primitive de $\cos x$ est $+\sin x$ (sans signe). Le signe n''apparaît que dans la dérivée de cosinus, pas dans la primitive. Mémo : sin↔cos sans signe, cos↔-sin avec signe.');
SELECT public._patch_cp_sma('definite_integral', '$\int_a^b f(x) dx$ représente :', 'Géométriquement, $\int_a^b f(x)\,dx$ représente l''**aire signée** entre la courbe $y = f(x)$ et l''axe des abscisses, sur l''intervalle $[a, b]$. Aire **positive** quand $f > 0$ (courbe au-dessus de l''axe), **négative** quand $f < 0$ (courbe au-dessous). C''est *l''aire algébrique* — pas l''aire géométrique stricte qui serait toujours positive. Pour une vraie aire géométrique, intégrer $|f(x)|$.');
SELECT public._patch_cp_sma('definite_integral', '$\int_a^b f = -\int_b^a f$. Vrai ou faux ?', '**Vrai**. Inverser les bornes d''une intégrale change le signe : $\int_a^b f = -\int_b^a f$. Cette propriété est cohérente avec la convention que $\int_a^a f = 0$ et avec la relation de Chasles. Conséquence pratique : si on calcule $F(b) - F(a)$ pour $\int_a^b$, alors $\int_b^a$ donne $F(a) - F(b)$ — le signe opposé.');
SELECT public._patch_cp_sma('definite_integral', '$\int_0^2 x\,dx = ?$', 'On cherche une primitive de $x$ : c''est $x^2/2$. Par Newton-Leibniz : $\int_0^2 x\,dx = \left[\dfrac{x^2}{2}\right]_0^2 = \dfrac{4}{2} - 0 = 2$. **Vérification géométrique** : la courbe $y = x$ entre 0 et 2 est un triangle rectangle de base 2 et hauteur 2, donc aire = $2 \times 2 / 2 = 2$ ✓. Cohérent.');
SELECT public._patch_cp_sma('integral_apps', 'L''aire entre $y = x^2$ et $y = 0$ sur $[0,1]$ vaut :', 'L''aire est $\int_0^1 x^2 dx = \left[\dfrac{x^3}{3}\right]_0^1 = \dfrac{1}{3} - 0 = \dfrac{1}{3}$. **Vérification d''ordre de grandeur** : sur $[0, 1]$, $x^2$ varie de 0 à 1 ; l''aire moyenne sous la courbe est environ $1/3$ — cohérent avec la formule $\int x^n = x^{n+1}/(n+1)$ qui donne précisément $1/(n+1)$ pour les bornes 0 et 1.');
SELECT public._patch_cp_sma('integral_apps', 'Une valeur moyenne de $f$ sur $[a,b]$ est :', 'La **valeur moyenne** d''une fonction continue sur $[a, b]$ est $\bar{f} = \dfrac{1}{b - a} \int_a^b f(x)\,dx$. Géométriquement, c''est la hauteur d''un rectangle de largeur $b - a$ qui aurait la même aire que sous la courbe. Application : si $f(t)$ est une vitesse instantanée, $\bar{f}$ est la vitesse moyenne. **Théorème de la moyenne** : il existe $c \in [a, b]$ tel que $f(c) = \bar{f}$ — la fonction prend sa moyenne au moins une fois si elle est continue.');
SELECT public._patch_cp_sma('prob_basic', 'On lance un dé à 6 faces. Probabilité d''obtenir un 3 ?', 'Sur un dé équilibré à 6 faces, chaque face a une probabilité égale d''apparaître. Il y a 1 face « 3 » sur 6 faces possibles, donc $P(\text{3}) = 1/6$. **Définition probabilité uniforme** : $P(A) = \dfrac{\text{nombre de cas favorables}}{\text{nombre de cas possibles}}$. Cette formule s''applique uniquement quand toutes les issues sont équiprobables — c''est le cas pour un dé non truqué.');
SELECT public._patch_cp_sma('prob_basic', 'Si $P(A) = 0{,}3$, alors $P(\bar{A}) = ?$', 'L''événement $\bar{A}$ (le **contraire** de $A$) regroupe toutes les issues où $A$ ne se produit pas. Comme $A$ et $\bar{A}$ couvrent toutes les possibilités sans se chevaucher : $P(A) + P(\bar{A}) = 1$. Donc $P(\bar{A}) = 1 - 0{,}3 = 0{,}7$. **Astuce** : passer au complémentaire est souvent plus simple que de calculer $P(A)$ directement (« probabilité d''au moins un » → calculer « probabilité d''aucun » et soustraire de 1).');
SELECT public._patch_cp_sma('prob_basic', '$P(A \cup B) = ?$ (général)', 'La **formule d''inclusion-exclusion** : $P(A \cup B) = P(A) + P(B) - P(A \cap B)$. On retire $P(A \cap B)$ pour ne pas compter deux fois les issues où $A$ et $B$ se produisent en même temps. **Cas particulier** : si $A$ et $B$ sont incompatibles ($A \cap B = \emptyset$), alors $P(A \cup B) = P(A) + P(B)$. **Erreur classique** : oublier le terme $-P(A \cap B)$ et obtenir une probabilité $> 1$.');
SELECT public._patch_cp_sma('conditional_prob', '$P(A | B) = ?$', 'La **probabilité conditionnelle** de $A$ sachant $B$ est $P(A | B) = \dfrac{P(A \cap B)}{P(B)}$ (avec $P(B) > 0$). Intuition : on se restreint à l''univers où $B$ s''est réalisé, et on regarde quelle fraction de cet univers correspond à $A \cap B$. **Formule des probabilités composées** (réécriture) : $P(A \cap B) = P(B) \cdot P(A | B)$ — utile quand on connaît la probabilité conditionnelle.');
SELECT public._patch_cp_sma('conditional_prob', '$A$ et $B$ sont indépendants ssi :', 'Deux événements sont **indépendants** ssi $P(A \cap B) = P(A) \cdot P(B)$ — la probabilité de l''intersection est le produit des probabilités. De manière équivalente : $P(A | B) = P(A)$ (la connaissance de $B$ ne change pas la probabilité de $A$). **Indépendance n''est pas incompatibilité** : indépendant = sans influence ; incompatible = ne peuvent coexister. Deux événements peuvent être l''un sans être l''autre.');
SELECT public._patch_cp_sma('random_variables', 'L''espérance $E(X)$ représente :', 'L''**espérance** $E(X)$ d''une variable aléatoire $X$ est la **valeur moyenne** qu''on obtiendrait en répétant l''expérience un grand nombre de fois — c''est la moyenne pondérée par les probabilités. Pour une v.a. discrète : $E(X) = \sum x_i \cdot P(X = x_i)$. **Interprétation** : si on parie sur $X$, on s''attend (en moyenne) à $E(X)$. Exemple : pour un dé équilibré à 6 faces, $E(X) = (1+2+3+4+5+6)/6 = 3{,}5$.');
SELECT public._patch_cp_sma('random_variables', '$V(X) = ?$ en fonction de $E(X)$', 'La **variance** mesure la dispersion autour de l''espérance : $V(X) = E((X - E(X))^2)$, ou de manière équivalente (formule de König) : $V(X) = E(X^2) - (E(X))^2$. La forme $E(X^2) - E(X)^2$ est souvent plus facile à calculer en pratique. **L''écart-type** $\sigma = \sqrt{V(X)}$ est l''unité de mesure de la dispersion (mêmes unités que $X$). Une variance nulle signifie que $X$ est constante ; plus elle est grande, plus $X$ est dispersée.');
SELECT public._patch_cp_sma('complex_basics', '$i^2 = ?$', 'Par **définition** du nombre $i$ (unité imaginaire), $i^2 = -1$. C''est cette propriété qui distingue $\mathbb{C}$ de $\mathbb{R}$ — dans $\mathbb{R}$, aucun nombre au carré ne donne un négatif. **Conséquences** : $i^3 = i^2 \cdot i = -i$ ; $i^4 = (i^2)^2 = 1$ ; les puissances de $i$ cyclent par 4 : $1, i, -1, -i, 1, i, \dots$. Cette cyclicité est très utile pour simplifier $i^n$ pour de grandes valeurs de $n$.');
SELECT public._patch_cp_sma('complex_basics', '$|3 + 4i| = ?$', 'Le **module** d''un complexe $z = a + bi$ est $|z| = \sqrt{a^2 + b^2}$ — c''est la distance à l''origine dans le plan complexe. Pour $3 + 4i$ : $|z| = \sqrt{9 + 16} = \sqrt{25} = 5$. **Astuce** : reconnaître le triplet pythagoricien (3, 4, 5) — ce sont des nombres très courants dans les exercices, mémoriser $|3+4i| = 5$ fait gagner du temps.');
SELECT public._patch_cp_sma('complex_basics', 'Conjugué de $2 - 3i$ ?', 'Le **conjugué** de $z = a + bi$ est $\bar{z} = a - bi$ — on change le signe de la partie imaginaire seulement. Donc $\overline{2 - 3i} = 2 + 3i$. **Propriétés clés** : $z \cdot \bar{z} = a^2 + b^2 = |z|^2$ (réel positif) ; $\overline{\bar{z}} = z$ ; le conjugué transforme une division en multiplication, d''où la technique « multiplier par le conjugué » pour simplifier $\dfrac{1}{a+bi}$.');
SELECT public._patch_cp_sma('complex_trig', 'Forme trigonométrique de $1 + i$ ?', 'Pour mettre sous forme trigonométrique $z = r(\cos\theta + i\sin\theta)$, on calcule module et argument. Module : $|1 + i| = \sqrt{1 + 1} = \sqrt{2}$. Argument : $\tan\theta = 1/1 = 1$ avec $z$ dans le quadrant 1 (parties réelle et imaginaire positives), donc $\theta = \pi/4$. Forme : $1 + i = \sqrt{2}(\cos(\pi/4) + i\sin(\pi/4)) = \sqrt{2} e^{i\pi/4}$.');
SELECT public._patch_cp_sma('complex_trig', 'Avec $z = re^{i\theta}$, $z^n = ?$', '**Formule de Moivre** : $z^n = r^n e^{in\theta}$. Multiplier les complexes en forme exponentielle revient à **multiplier les modules et additionner les arguments** ; donc élever à la puissance $n$ multiplie l''argument par $n$. Application typique : $(1+i)^4 = (\sqrt{2})^4 e^{i\pi} = 4 \cdot (-1) = -4$ (calcul instantané vs développement laborieux).');
SELECT public._patch_cp_sma('complex_geometry', 'Le module $|z_B - z_A|$ représente :', '$|z_B - z_A|$ est la **distance** entre les points $A$ et $B$ d''affixes $z_A$ et $z_B$ dans le plan complexe. C''est une simple application du module comme distance à l''origine, appliquée au vecteur $\vec{AB}$ d''affixe $z_B - z_A$. **Application** : pour montrer que trois points sont alignés, équidistants, ou forment un triangle particulier, calculer les modules $|z_B - z_A|$, $|z_C - z_B|$, etc.');
SELECT public._patch_cp_sma('complex_geometry', '$\arg(z_B - z_A)$ représente :', '$\arg(z_B - z_A)$ est l''**angle** que forme le vecteur $\vec{AB}$ avec l''axe réel positif (axe Ox), mesuré dans le sens trigonométrique. Couplé au module $|z_B - z_A|$, cela donne les coordonnées polaires du vecteur $\vec{AB}$. **Application** : un triangle est équilatéral ssi les trois côtés ont même longueur (modules égaux) et les angles correspondent.');
SELECT public._patch_cp_sma('ode_first_order', 'Solution générale de $y'' = ky$ ?', 'L''équation $y'' = ky$ (croissance/décroissance proportionnelle) a pour solution générale $y(x) = C e^{kx}$ avec $C \in \mathbb{R}$. **Démonstration intuitive** : si la dérivée est proportionnelle à la fonction, on tombe naturellement sur l''exponentielle (qui est sa propre dérivée à un facteur près). $C$ est déterminée par une condition initiale (ex : $y(0) = y_0$ donne $C = y_0$). Modélise désintégration radioactive ($k < 0$), croissance bactérienne ($k > 0$), etc.');
SELECT public._patch_cp_sma('ode_first_order', 'Solution de $y'' + 2y = 0$, $y(0) = 5$ ?', 'L''équation $y'' + 2y = 0$ se réécrit $y'' = -2y$, donc solution générale $y(x) = C e^{-2x}$. Condition initiale : $y(0) = C e^0 = C = 5$. Donc $y(x) = 5 e^{-2x}$. **Vérification** : $y''(x) = -10 e^{-2x} = -2 \cdot 5 e^{-2x} = -2 y$ ✓. La fonction décroît exponentiellement de 5 vers 0.');
SELECT public._patch_cp_sma('ode_second_order', '$y'''' + \omega^2 y = 0$ a pour solutions :', 'L''équation $y'''' + \omega^2 y = 0$ (oscillateur harmonique non amorti) a pour solution générale $y(x) = A \cos(\omega x) + B \sin(\omega x)$ avec $A, B \in \mathbb{R}$. **Vérification** : $(\cos\omega x)'''' = -\omega^2 \cos\omega x$, donc $\cos\omega x$ vérifie l''équation ✓. Cette équation modélise le pendule simple (petites oscillations), un ressort idéal, un circuit LC, etc. La pulsation $\omega$ détermine la période $T = 2\pi/\omega$.');
SELECT public._patch_cp_sma('kinematics', 'L''accélération est la dérivée de :', 'L''**accélération** $a(t)$ est la dérivée de la **vitesse** $v(t)$ par rapport au temps : $a = dv/dt$. C''est aussi la **dérivée seconde** de la position : $a = d^2x/dt^2$. Mémo : position $\xrightarrow{d/dt}$ vitesse $\xrightarrow{d/dt}$ accélération. Inversement : on intègre l''accélération pour retrouver la vitesse, puis encore une fois pour la position.');
SELECT public._patch_cp_sma('kinematics', 'En MRUA, $v(t) = ?$', 'Mouvement Rectiligne Uniformément Accéléré (MRUA) : accélération constante $a$. Par intégration : $v(t) = v_0 + a t$, où $v_0$ est la vitesse initiale. **Cohérence avec la dérivée** : $dv/dt = a$ ✓. Position : $x(t) = x_0 + v_0 t + \dfrac{1}{2} a t^2$ — équation de la chute libre, du démarrage d''une voiture, etc. À $g = 9{,}8 \text{ m/s}^2$, en chute libre la vitesse augmente d''environ 10 m/s par seconde.');
SELECT public._patch_cp_sma('newtons_laws', '$\sum \vec{F} = ?$ (2ème loi de Newton)', '**Deuxième loi de Newton** : $\sum \vec{F} = m \vec{a}$ — la somme vectorielle des forces appliquées à un objet égale sa masse fois son accélération. C''est l''équation fondamentale de la dynamique. **Conséquences** : si $\sum \vec{F} = \vec{0}$, alors $\vec{a} = \vec{0}$ (équilibre dynamique) ; si une force unique $F$ est appliquée, $a = F/m$ — accélération inversement proportionnelle à la masse.');
SELECT public._patch_cp_sma('newtons_laws', 'Principe d''inertie (1ère loi) :', '**Première loi de Newton** (principe d''inertie) : un objet sur lequel s''exerce une somme de forces nulle est en mouvement rectiligne uniforme (MRU) ou au repos. Inversement, tout changement de vitesse (en module ou en direction) implique une force non nulle. **Conséquence pratique** : un objet en mouvement n''a pas besoin d''une force pour continuer à se déplacer — c''est l''inertie qui le maintient. Idée révolutionnaire d''Aristote à Newton.');
SELECT public._patch_cp_sma('energy', 'Énergie cinétique $E_c = ?$', 'L''**énergie cinétique** d''un objet en mouvement est $E_c = \dfrac{1}{2} m v^2$ — proportionnelle à la masse et au **carré** de la vitesse (pas à la vitesse linéaire !). Doubler la vitesse quadruple l''énergie cinétique. **Unités** : kg·(m/s)² = J (joule). Application : un véhicule à 100 km/h a 4× l''énergie d''un véhicule à 50 km/h — d''où la distance de freinage qui croît rapidement avec la vitesse.');
SELECT public._patch_cp_sma('energy', 'Théorème de l''énergie cinétique :', '$\Delta E_c = W_{\text{forces}}$ — la **variation de l''énergie cinétique** d''un objet égale la **somme des travaux** des forces appliquées entre les deux instants. C''est un théorème puissant : il convertit un problème dynamique (forces, accélérations) en un problème énergétique (scalaire, plus simple). **Application typique** : calculer la vitesse d''un objet en bas d''un toboggan sans résoudre l''équation de mouvement complète.');
SELECT public._patch_cp_sma('wave_properties', '$v = \lambda f$ relie :', 'La relation fondamentale des ondes : **vitesse = longueur d''onde × fréquence**. $v$ en m/s, $\lambda$ en m, $f$ en Hz (1/s). Cette équation est universelle — vrai pour ondes mécaniques (corde, son), électromagnétiques (lumière), de matière (de Broglie). **Application** : pour la lumière dans le vide, $v = c \approx 3 \times 10^8$ m/s, donc une couleur de longueur d''onde $\lambda = 500$ nm a une fréquence $f = c/\lambda = 6 \times 10^{14}$ Hz.');
SELECT public._patch_cp_sma('sound_light', 'La diffraction est observable quand :', 'La **diffraction** (déviation des ondes derrière un obstacle) est observable quand la dimension de l''ouverture/obstacle est de l''ordre de la longueur d''onde $\lambda$. **Critère** : largeur $a \lesssim \lambda$ → diffraction nette ; $a \gg \lambda$ → propagation rectiligne. Application : on entend le son derrière un mur (λ ~ 1 m, comparable aux objets) mais on ne voit pas (λ ~ 500 nm, beaucoup plus petit).');
SELECT public._patch_cp_sma('rc_rl_circuits', 'Constante de temps d''un circuit RC : $\tau = ?$', 'Pour un circuit RC série, la **constante de temps** est $\tau = RC$ (en secondes, avec $R$ en Ω et $C$ en F). Elle caractérise la rapidité de la charge/décharge : à $t = \tau$, le condensateur est chargé à 63% ($1 - e^{-1}$) ; à $t = 5\tau$, à plus de 99% — on considère le régime établi. **Mémo** : $\tau$ grand = charge lente ; $\tau$ petit = charge rapide. Pour un circuit RL, $\tau = L/R$.');
SELECT public._patch_cp_sma('rlc_oscillations', 'Pulsation propre LC : $\omega_0 = ?$', 'Pour un circuit LC idéal (sans résistance), la **pulsation propre** est $\omega_0 = \dfrac{1}{\sqrt{LC}}$ (en rad/s). La période d''oscillation est $T_0 = 2\pi/\omega_0 = 2\pi\sqrt{LC}$. **Analogie mécanique** : $L$ joue le rôle de la masse (inertie), $C$ celui de l''inverse de la raideur ($1/k$) — un circuit LC est l''équivalent électrique d''un oscillateur harmonique mécanique. Avec une résistance $R$ ajoutée, les oscillations s''amortissent (analogue d''un amortisseur).');
SELECT public._patch_cp_sma('acid_base', '$pH = -\log_{10}([H_3O^+])$. Si $[H_3O^+] = 10^{-3}$ mol/L, $pH = ?$', '$pH = -\log_{10}(10^{-3}) = -(-3) = 3$. **Mémo** : $pH$ = exposant changé de signe de la concentration en ions hydronium, exprimée comme puissance de 10. Solution acide ($pH < 7$) : forte concentration en $H_3O^+$ ; basique ($pH > 7$) : faible concentration. **Échelle log** : $\Delta pH = 1$ correspond à un facteur 10 sur $[H_3O^+]$.');
SELECT public._patch_cp_sma('acid_base', 'Une solution avec $pH = 13$ est :', '$pH = 13 > 7$ : la solution est **basique** (concentration en $H_3O^+$ très faible : $10^{-13}$ mol/L). $pH$ proche de 14 (la limite haute en solution aqueuse) → solution **fortement basique**. Exemples : soude concentrée, lessive, ammoniaque. À l''inverse : $pH \le 1$ = fortement acide (acide chlorhydrique, jus gastrique). $pH = 7$ = neutre (eau pure à 25°C).');
SELECT public._patch_cp_sma('redox', 'Une oxydation est :', 'Une **oxydation** est une **perte d''électrons** par une espèce. Notation : $\text{Red} \to \text{Ox} + n e^-$. **Mémo OIL RIG** : Oxidation Is Loss (of electrons), Reduction Is Gain. Exemple : $Zn \to Zn^{2+} + 2 e^-$ (oxydation du zinc). À l''inverse : réduction = gain d''électrons. Les deux se produisent simultanément dans une réaction redox — l''un cède, l''autre prend.');
SELECT public._patch_cp_sma('redox', 'Dans une pile, l''anode est le siège de :', 'À l''**anode** d''une pile, c''est l''**oxydation** qui a lieu — l''espèce y perd des électrons, qui partent dans le circuit extérieur. Anode = pôle **négatif** d''une pile (par convention électrique, c''est de là que sortent les électrons). Mémo : Anode → ox**A**ydation ; **C**athode → ré**du**ction. À la cathode (pôle positif), les électrons arrivent et réduisent une espèce.');

DROP FUNCTION public._patch_cp_sma(TEXT, TEXT, TEXT);
DROP FUNCTION public._patch_tryit_sma(TEXT, TEXT, TEXT, TEXT);

COMMIT;
